import { readdir, lstat, readFile, rm } from 'node:fs/promises';
import path from 'node:path';

export const JOB_RETENTION_MS = 24 * 60 * 60 * 1000;
const jobId = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** Remove only expired, marked outputs generated by this worker. Never follow links. */
export async function expireJobs(root: string, running: Set<string>, now = Date.now()) {
  const base = path.resolve(root);
  const removed: string[] = [];
  for (const entry of await readdir(base, { withFileTypes: true })) {
    if (
      !jobId.test(entry.name) ||
      !entry.isDirectory() ||
      entry.isSymbolicLink() ||
      running.has(entry.name)
    )
      continue;
    const target = path.resolve(base, entry.name);
    if (path.dirname(target) !== base) continue;
    try {
      const marker = path.join(target, '.sarflow-job.json');
      const info = await lstat(marker);
      if (!info.isFile() || info.isSymbolicLink() || info.size > 1024) continue;
      const record = JSON.parse(await readFile(marker, 'utf8'));
      if (
        record.id !== entry.name ||
        typeof record.created !== 'number' ||
        !Number.isFinite(record.created) ||
        now - record.created < JOB_RETENTION_MS
      )
        continue;
      await rm(target, { recursive: true });
      removed.push(entry.name);
    } catch {
      /* Unrecognized or inaccessible artifacts remain untouched. */
    }
  }
  return removed;
}
